def print_mask(mask_trail, nb_rounds):
    """打印 128-bit mask trail"""
    for n in range(nb_rounds):
        for i in range(BLOCK_SIZE):
            print(mask_trail[n][0][i], end='')
            if i % 4 == 3:
                print(' ', end='')
        print()
        for i in range(BLOCK_SIZE):
            print(mask_trail[n][1][i], end='')
            if i % 4 == 3:
                print(' ', end='')
        print()
    print()


def compute_correlation(diff_trail, mask_trail, nb_rounds):
    conditions = [[[] for _ in range(BLOCK_SIZE)] for _ in range(nb_rounds)]
    corr = 1   
    for k in range(nb_rounds):
        for i in range(NB_SBOXES):   
            a_bits = diff_trail[k][0][4*i:4*i+4]
            b_bits = diff_trail[k][1][4*i:4*i+4]
            u_bits = mask_trail[k][0][4*i:4*i+4]
            v_bits = mask_trail[k][1][4*i:4*i+4]
            
            a = bin_to_int(a_bits, SBOX_SIZE)
            b = bin_to_int(b_bits, SBOX_SIZE)
            u = bin_to_int(u_bits, SBOX_SIZE)
            v = bin_to_int(v_bits, SBOX_SIZE)
            
            corr *= QDTM_GIFT_SBOX[b][a][v][u]
            if QDTM_GIFT_SBOX[b][a][v][u] == 0:
                return "Error"
    for k in range(nb_rounds):
        corr *= character([1], [mask_trail[k][1][0]], 1)                            
        corr *= character([(AC_STATES[k] >> 5) & 1], [mask_trail[k][1][104]], 1)    
        corr *= character([(AC_STATES[k] >> 4) & 1], [mask_trail[k][1][108]], 1)    
        corr *= character([(AC_STATES[k] >> 3) & 1], [mask_trail[k][1][112]], 1)    
        corr *= character([(AC_STATES[k] >> 2) & 1], [mask_trail[k][1][116]], 1)    
        corr *= character([(AC_STATES[k] >> 1) & 1], [mask_trail[k][1][120]], 1)    
        corr *= character([(AC_STATES[k] >> 0) & 1], [mask_trail[k][1][124]], 1)    
    
    for k in range(nb_rounds):
        for j in range(BLOCK_SIZE):
            if mask_trail[k][0][j] == 0:
                continue
            
            elif j % 4 == 1 or j % 4 == 2:
                conditions[k][j] = mask_trail[k][0][j]
            else:
                continue
    
    if corr > 0:
        return  1, log2( corr), conditions
    elif corr < 0:
        return -1, log2(-corr), conditions
    return 1, 0, []


def add_xor_constraints(model, x1, x2, y):
    model.addConstr(-x1 + x2 + y >= 0)
    model.addConstr( x1 - x2 + y >= 0)
    model.addConstr( x1 + x2 - y >= 0)
    model.addConstr(-x1 - x2 - y >= -2)


def add_xor_constraints2(model, x1, x2, x3, y):
    model.addConstr(-x1 + x2 + x3 + y >= 0)
    model.addConstr( x1 - x2 + x3 + y >= 0)
    model.addConstr( x1 + x2 - x3 + y >= 0)
    model.addConstr( x1 + x2 + x3 - y >= 0)
    model.addConstr( x1 - x2 - x3 - y >= -2)
    model.addConstr(-x1 + x2 - x3 - y >= -2)
    model.addConstr(-x1 - x2 + x3 - y >= -2)
    model.addConstr(-x1 - x2 - x3 + y >= -2)

def build_key_map_GIFT128(max_rounds):
    key_map = []
    for r in range(max_rounds):
        U, V = key_schedule(r)
        row = []
        for subkey_idx in range(64):   
            
            if subkey_idx % 2 == 0:
                row.append(V[31 - (subkey_idx // 2)])
            else:
                row.append(U[31 - (subkey_idx // 2)])
        key_map.append(row)
    return key_map

def GIFT_MILP_Quasi_Diff(nb_rounds,mask_range,LOW_BOUND=MIN_CORR ,all=True):
    diff_trail = extract_diff_trail(DIFF_TRAIL_FILE, nb_rounds)
    sbox_inequalities = extract_inequalities_by_corr(SBOX_INEQUALITIES_DIR, SBOX_SIZE)
    model = Model("GIFT128_SK_Quasi_Diff_MILP")
    
    
    u = model.addVars(nb_rounds, 2, BLOCK_SIZE, vtype=GRB.BINARY, name="m")    
    Q = model.addVars(nb_rounds, NB_SBOXES, CORR_RANGE, vtype=GRB.BINARY, name="c")  
    
    
    model.addConstrs(u[0, 0, l] == 0 for l in range(BLOCK_SIZE))
    model.addConstrs(u[nb_rounds - 1, 1, l] == 0 for l in range(BLOCK_SIZE))
    allowed_masks = set(mask_range)
    print(f"Applying mask range constraints (Allowed bits: {len(allowed_masks)})...")
    
    for r in range(nb_rounds):
        for before in range(2):
            for l in range(128):
                if (r, before, l) not in allowed_masks:
                    model.addConstr(u[r, before, 127 - l] == 0,
                                    name=f"mask_limit_{r}_{before}_{127-l}")
     
    
    for r in tqdm(range(nb_rounds)):
        for i in range(NB_SBOXES):
            b = bin_to_int([diff_trail[r][1][4*i+l] for l in range(4)], SBOX_SIZE)
            a = bin_to_int([diff_trail[r][0][4*i+l] for l in range(4)], SBOX_SIZE)
            
            model.addConstr(quicksum(Q[r, i, corr] for corr in CORR_RANGE) == 1)
            for corr in CORR_RANGE:
                if sbox_inequalities[b][a][corr] == []:
                    model.addConstr(Q[r, i, corr] == 0)
                    continue
                for ineq in sbox_inequalities[b][a][corr]:
                    model.addConstr(
                        quicksum(ineq[0*SBOX_SIZE + l] * u[r, 1, 4*i + l] for l in BIT_RANGE) +
                        quicksum(ineq[1*SBOX_SIZE + l] * u[r, 0, 4*i + l] for l in BIT_RANGE) +
                        ineq[2*SBOX_SIZE] + 500000 * (1 - Q[r, i, corr]) >= 0
                    )
    
    
    for r in range(nb_rounds - 1):
        model.addConstrs(
            u[r, 1, l] == u[r + 1, 0, (BLOCK_SIZE - 1) - BIT_PERM[(BLOCK_SIZE - 1) - l]]
            for l in range(BLOCK_SIZE)
        )
    
    model.write("gift128_fixed_key.lp")
    
    
    total_corr = quicksum(
        Q[r, i, corr] * corr
        for r in range(nb_rounds) for i in range(NB_SBOXES) for corr in CORR_RANGE
    )
    model.addConstr(total_corr >= -LOW_BOUND)
    
    
    model.setObjective(total_corr, GRB.MAXIMIZE)
    
    model.params.PoolSearchMode = 2
    model.params.PoolSolutions = 2000000
    
    t1 = time.time()
    model.optimize()
    print(f"Time used: {time.time()-t1:.2f}s")
    print(f"Found {model.SolCount} trails")
    
    
    print("Computing sign and conditions for each trail...")
    signs = []
    correlations = []
    trails_conditions = []
    corr_dict = {}
    avg_prob = None
    
    for m in tqdm(range(model.SolCount)):
        model.params.SolutionNumber = m
        mask_trail = [
            [
                [round(u[r, side, l].Xn) for l in range(BLOCK_SIZE)]
                for side in range(2)
            ]
            for r in range(nb_rounds)
        ]
        result = compute_correlation(diff_trail, mask_trail, nb_rounds)
        if result == "Error":
            continue
        sign, corr, conditions = result
        if avg_prob is None:
            avg_prob = corr
        
        corr_dict[corr] = corr_dict.get(corr, 0) + 1
        signs.append(sign)
        correlations.append(corr)
        trails_conditions.append(conditions)
    
    print(f"Solution numbers: {model.SolCount}")
    
    
    key_map = build_key_map_GIFT128(nb_rounds)
    print(f"Built key_map for {len(key_map)} rounds")
    

    T = []
    for i in range(len(signs)):
        k_lst = []
        
        for r in range(1, len(trails_conditions[i])):
            for j in range(len(trails_conditions[i][r])):
                if trails_conditions[i][r][j] != []:
                    bit = BLOCK_SIZE - 1 - j        
                    nibble_idx = bit // 4           
                    bit_in_nibble = bit % 4         
                    
                    if bit_in_nibble == 1:
                        
                        subkey_idx = nibble_idx * 2
                        k = key_map[r-1][subkey_idx]
                        
                        k_lst.append(f'k_{127-k}')
                    elif bit_in_nibble == 2:
                        
                        subkey_idx = nibble_idx * 2 + 1
                        k = key_map[r-1][subkey_idx]
                        
                        k_lst.append(f'k_{127-k}')
                    else:
                        print(f"Error: condition at bit [{bit}] is not a key injection bit")
        
        T.append({
            'sign': signs[i],
            'corr': correlations[i],
            'keys': k_lst,
        })
    
    print(f"Valid trails: {len(T)}, base correlation: {avg_prob}")
    if(len(T)<10):
        print("DITRIBUTION: ",T)
    
    
    if avg_prob is None:
        return model.SolCount, {}
    
    distribution = compute_distribution_from_trails(T, avg_prob)
    print(f"Cluster distribution: {distribution}")
    return model.SolCount,distribution

def compute_distribution_from_trails(T, avg_p):
    print(avg_p)
    if len(T) == 0:
        return {}
    
    base_corr = (1) * avg_p
    
    unique_keys = set()
    for t in T:
        unique_keys.update(t['keys'])
    unique_keys = sorted(list(unique_keys))
    num_keys = len(unique_keys)
    
    if num_keys == 0:
        
        total = sum(t['sign'] * (2 ** (t['corr'] - base_corr)) for t in T)
        return {round(total, 10): 1}
    
    key_to_idx = {k: i for i, k in enumerate(unique_keys)}
    total_space = 2 ** num_keys
    
    
    num_samples = 8000
    if total_space <= num_samples:
        X = np.array(list(itertools.product([0, 1], repeat=num_keys)))
        actual = total_space
    else:
        X = np.random.randint(0, 2, size=(num_samples, num_keys))
        actual = num_samples
    
    total_sum = np.zeros(actual)
    for t in T:
        k_indices = [key_to_idx[k] for k in t['keys']]
        if len(k_indices) > 0:
            xor_sum = np.sum(X[:, k_indices], axis=1) % 2
        else:
            xor_sum = np.zeros(actual)
        term_val = t['sign'] * (2 ** (t['corr'] - base_corr)) * ((-1) ** xor_sum)
        total_sum += term_val
    
    
    rounded = np.round(total_sum, 10)
    return dict(sorted(Counter(rounded.tolist()).items()))


